export function searchServers(query: string, limit: number = 10): Server[] {
  const searchTerm = query.toLowerCase();
  return servers
    .filter(
      (server) =>
        server.name.toLowerCase().includes(searchTerm) ||
        server.description.toLowerCase().includes(searchTerm) ||
        server.category.toLowerCase().includes(searchTerm) ||
        server.author.toLowerCase().includes(searchTerm) ||
        server.features.toLowerCase().includes(searchTerm)
    )
    .slice(0, limit);
}

export function getServerById(id: string): Server | undefined {
  return servers.find((s) => s.id === id);
}

export function getServersByCategory(category: string): Server[] {
  return servers.filter((s) => s.category === category);
}

export function getAllServers(): Server[] {
  return servers;
}
